/** Mock interview (self-practice) API shapes — mirror backend/app/schemas/mock_interview.py. */

export type MockInterviewType = 'mixed' | 'technical' | 'behavioral' | 'hr';
export type MockDifficulty = 'easy' | 'medium' | 'hard';
export type MockQuestionType = 'technical' | 'behavioral' | 'hr';
/** 'ai' = generated by the model; 'basic' = built-in questions / rule-based feedback. */
export type MockSource = 'ai' | 'basic';

export interface MockQuestionsRequest {
  role: string;
  jobDescription: string;
  resumeText: string;
  interviewType: MockInterviewType;
  difficulty: MockDifficulty;
  count: number;
}

export interface MockQuestion {
  id: number;
  question: string;
  type: MockQuestionType;
  /** What a strong answer should show. */
  focus: string;
}

export interface MockQuestionsResponse {
  questions: MockQuestion[];
  source: MockSource;
}

export interface MockFeedbackRequest {
  question: string;
  questionType: MockQuestionType;
  answer: string;
  role: string;
  jobDescription: string;
  resumeText: string;
}

export interface MockFeedback {
  /** 1 (weak) … 10 (excellent). */
  score: number;
  summary: string;
  strengths: string[];
  improvements: string[];
  sampleAnswer: string[];
  source: MockSource;
}
